  "data": {
    "name": "useTableStickyColumns",
    "subComponentOf": "Table",
    "displayName": "useTableStickyColumns",
    "description": "Hook that returns a TablePlugin which pins a contiguous run of columns to the start and/or end edge of the table. Pinned columns get cumulative offsets and a soft, scroll-aware shadow over the scrolling content. An empty config ({}) is a valid no-op that pins nothing.",
    "props": [
      {
        "name": "startKeys",
        "type": "string[]",
        "description": "Column keys pinned to the start (inline-start / left in LTR) edge: the contiguous run from the first column through the last listed key."
      },
      {
        "name": "endKeys",
        "type": "string[]",
        "description": "Column keys pinned to the end (inline-end / right in LTR) edge: the contiguous run from the first listed key through the last column."
      }
    ]
  },
